function validate([num]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 100) return 'num needs 1 to 100 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num contains only digits.';
  if (num.length > 1 && num[0] === '0') return 'num has no leading zeros.';
  return null;
}

