function minimumOperations(num) {
  const n = num.length;
  let seenZero = false;
  let seenFive = false;
  for (let i = n - 1; i >= 0; i--) {
    const digit = num[i];
    if ((digit === '0' || digit === '5') && seenZero) {
      return n - i - 2;
    }
    if ((digit === '2' || digit === '7') && seenFive) {
      return n - i - 2;
    }
    if (digit === '0') {
      seenZero = true;
    }
    if (digit === '5') {
      seenFive = true;
    }
  }
  return seenZero ? n - 1 : n;
}

