function minimumOperations(num) {
  // Try every set of kept digits and check the value modulo 25.
  const n = num.length;
  let best = n;
  for (let mask = 0; mask < (1 << n); mask++) {
    let rest = 0;
    let kept = 0;
    for (let i = 0; i < n; i++) {
      if ((mask >> i) & 1) {
        rest = (rest * 10 + Number(num[i])) % 25;
        kept++;
      }
    }
    if (rest === 0) best = Math.min(best, n - kept);
  }
  return best;
}

