function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 10);
  // Some inputs avoid the helpful digits so the fallback answers appear too.
  const pools = ['0123456789', '0257', '13467899', '1234678', '05', '2457'];
  const pool = pools[Math.floor(rand() * pools.length)];
  let num = '';
  for (let i = 0; i < n; i++) num += pool[Math.floor(rand() * pool.length)];
  if (n > 1 && num[0] === '0') num = String(1 + Math.floor(rand() * 9)) + num.slice(1);
  return [num];
}
